// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/domain/brief.ts`. Edit the source and run `just generate`.
// The check of the sections of a package brief: each section of `PACKAGE_SECTIONS` is a `## ` heading, in order, and holds text.
// Plain data and pure functions only.

import { type FormatError, PACKAGE_SECTIONS } from "./formats.ts";
import { fail, fenceMask, toLines } from "./lines.ts";

/** A level-2 heading, with its name. */
const H2 = /^## (\S.*?)\s*$/;

/** A level-1 heading. The front matter `title` is the only title of a package. */
const H1 = /^# \S/;

/** The errors of the sections of the brief `text`: a missing, an extra, a repeated, or an empty `## ` section. */
export const sectionErrors = (text: string): FormatError[] => {
  const lines = toLines(text);
  const fenced = fenceMask(lines);
  const heads = lines.flatMap((l, i) => {
    const name = fenced[i] ? undefined : H2.exec(l.text)?.[1];
    return name === undefined ? [] : [{ name, index: i, line: l.line }];
  });
  const errors: FormatError[] = [];
  for (const [i, l] of lines.entries())
    if (!fenced[i] && H1.test(l.text))
      errors.push(
        fail(l.line, "a package has no `# ` heading, its title is `title`"),
      );
  const names = heads.map((h) => h.name);
  for (const section of PACKAGE_SECTIONS)
    if (!names.includes(section))
      errors.push(fail(1, `missing section \`## ${section}\``));
  for (const [n, head] of heads.entries()) {
    const known = (PACKAGE_SECTIONS as readonly string[]).includes(head.name);
    if (!known)
      errors.push(fail(head.line, `unknown section \`## ${head.name}\``));
    else if (names.indexOf(head.name) !== n)
      errors.push(fail(head.line, `repeated section \`## ${head.name}\``));
    const end = heads[n + 1]?.index ?? lines.length;
    const body = lines.slice(head.index + 1, end).some((l) => l.text.trim());
    if (known && !body)
      errors.push(fail(head.line, `section \`## ${head.name}\` is empty`));
  }
  const order = names.filter((name) =>
    (PACKAGE_SECTIONS as readonly string[]).includes(name),
  );
  const wanted = PACKAGE_SECTIONS.filter((s) => order.includes(s));
  if (order.join() !== wanted.join() && errors.length === 0)
    errors.push(
      fail(1, `sections are in order: ${PACKAGE_SECTIONS.join(", ")}`),
    );
  return errors;
};

/** The text of the section `name` of the brief `text`, without its heading, or an empty string when the section is missing. */
export const sectionOf = (text: string, name: string): string => {
  const lines = toLines(text);
  const fenced = fenceMask(lines);
  const isHead = (i: number): boolean =>
    !fenced[i] && H2.test(lines[i]?.text ?? "");
  const start = lines.findIndex(
    (l, i) => isHead(i) && H2.exec(l.text)?.[1] === name,
  );
  if (start < 0) return "";
  const rest = lines.slice(start + 1);
  const stop = rest.findIndex((_, i) => isHead(start + 1 + i));
  return rest
    .slice(0, stop < 0 ? undefined : stop)
    .map((l) => l.text)
    .join("\n")
    .trim();
};
